 const candidateTabs=[['profile','user','Thông tin cá nhân'],['resumes','document','CV của tôi'],['builder','pen','Tạo CV mới'],['applications','briefcase','Việc đã ứng tuyển'],['saved','bookmark','Việc đã lưu'],['notifications','bell','Thông báo']];
